class Solution {
    fun shortestPathLength(graph:Array<IntArray>):Int{
        val n=graph.size;
        val target=(1 shl n)-1;
        val seen=Array(n){
            BooleanArray(1 shl n)
        };
        val queue=java.util.ArrayDeque<IntArray>();
        for(node in 0 until n){
            queue.addLast(intArrayOf(node,1 shl node,0));
            seen[node][1 shl node]=true
        };
        while(queue.isNotEmpty()){
            val state=queue.removeFirst();
            if(state[1]==target)return state[2];
            for(next in graph[state[0]]){
                val mask=state[1] or (1 shl next);
                if(!seen[next][mask]){
                    seen[next][mask]=true;
                    queue.addLast(intArrayOf(next,mask,state[2]+1))
                }
            }
        };
        return -1
    }
}

